import { createAppLogger } from "@rome-os/app-runtime";
import type {
  ActionEngineLike,
  ChannelAdapter,
  ChannelMessageHook as ChannelMessageHookInterface,
  NormalizedMessage,
} from "@rome-os/app-runtime";

const log = createAppLogger("channel-message-hook");

export class ChannelMessageHook implements ChannelMessageHookInterface {
  constructor(
    private actionEngine: ActionEngineLike,
    private channelAdapters: Map<string, ChannelAdapter>,
  ) {}

  /** Register the message handler hook on all active channel adapters. */
  register(): void {
    for (const [, adapter] of this.channelAdapters) {
      this.registerAdapter(adapter);
    }
  }

  /** Register the message handler hook on a single adapter. */
  registerAdapter(adapter: ChannelAdapter): void {
    adapter.onMessage(async (msg: NormalizedMessage) => {
      if (!msg.text?.trim() && msg.attachments.length === 0) {
        log.debug("skipping empty message", { channel: msg.channel, messageId: msg.id });
        return;
      }

      let attachments = msg.attachments;
      if (attachments.length > 0 && typeof adapter.saveIncomingAttachments === "function") {
        try {
          attachments = await adapter.saveIncomingAttachments(msg);
        } catch (err) {
          log.error("failed to save incoming attachments", {
            channel: msg.channel,
            messageId: msg.id,
            error: err instanceof Error ? err.message : String(err),
          });
        }
      }

      // Show typing indicator while processing (Discord and any adapter that supports it)
      let typingInterval: ReturnType<typeof setInterval> | undefined;
      if (typeof adapter.notifyTyping === "function") {
        adapter.notifyTyping(msg.threadId).catch(() => {});
        typingInterval = setInterval(() => {
          adapter.notifyTyping!(msg.threadId).catch(() => {});
        }, 9000);
      }

      try {
        await this.actionEngine.run(
          "message_handler",
          {
            channel: msg.channel,
            channelUserId: msg.channelUserId,
            threadName: msg.threadName,
            threadType: msg.threadType,
            threadId: msg.threadId,
            displayName: msg.displayName,
            text: msg.text,
            timestamp: msg.timestamp.toISOString(),
            attachments,
            messageId: msg.id,
            replyToMessageId: msg.replyToMessageId,
            // Per-channel routing override resolved by the channel adapter from
            // its channel config (e.g. Discord channel → custom agent). Only
            // honored by the trusted path; sentinel still triages untrusted.
            routedAgentName: msg.routing?.agentName,
          },
          {
            initiator: `channel:${msg.channel}`,
            channelContext: {
              channel: msg.channel,
              threadId: msg.threadId,
              channelUserId: msg.channelUserId,
              threadName: msg.threadName,
              threadType: msg.threadType,
            },
          },
        );
      } catch (err) {
        log.error("message_handler action failed", {
          channel: msg.channel,
          messageId: msg.id,
          channelUserId: msg.channelUserId,
          error: err instanceof Error ? err.message : String(err),
        });
      } finally {
        if (typingInterval !== undefined) clearInterval(typingInterval);
      }
    });
  }
}

export function createHook(deps: {
  actionEngine: ActionEngineLike;
  channelAdapters: Map<string, ChannelAdapter>;
}): ChannelMessageHookInterface {
  return new ChannelMessageHook(deps.actionEngine, deps.channelAdapters);
}
